import{z as o,x as d,o as t,c as n,q as A,j as B,D as E,d as e,s as l,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"SSD 与 FTL","description":"","frontmatter":{"title":"SSD 与 FTL","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/st-ssd-ftl.md","filePath":"cs/st-ssd-ftl.md","lastUpdated":1791063341000}'),C={name:"cs/st-ssd-ftl.md"};function F(p,a,D,T,c,f){const r=d("Mermaid");return t(),n("div",null,[a[2]||(a[2]=A('<h1 id="ssd-与-ftl" tabindex="-1">SSD 与 FTL <a class="header-anchor" href="#ssd-与-ftl" aria-label="Permalink to &quot;SSD 与 FTL&quot;">​</a></h1><div class="epigraph"><p>块接口许诺页可以原地覆盖；闪存只按页写、按块擦。FTL 在两者之间签一份翻译合同，写放大就是这份合同的价格表。</p><footer>—— 据 Agrawal et al., USENIX ATC 2008；Desnoyers, SYSTOR 2012；NVMe ZNS 规范整理</footer></div><p><a href="/cs/st-btree-implementation">上一课</a>把 B+ 实现的合同钉在页上，页可原地覆盖读写是合同成立的前提。本课去收介质对这份前提开的税单。主干已钉过 <a href="/cs/nand-ftl">NAND 闪存与 FTL</a> 的页写块擦与 L2P 映射的可恢复性、<a href="/cs/ssd-gc-wear">SSD 内部并行、GC 与磨损</a>的回收与均衡、<a href="/cs/discard-trim">discard 与 TRIM</a> 的空闲告知。深入问四个问题：映射粒度怎么选、超配留多大、随机写到底贵几倍、主机能替 FTL 做什么。后课默认：块设备的写放大是有价格表的，引擎与文件系统都是这张表的读者。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>页级映射：每个逻辑页一条表项，随机写零合并开销，但 1 TiB 盘按 4 KiB 粒度要两亿多条表项，几 GiB 的表自身要在 DRAM 与 NAND 间分级——映射表的容量本身就是成本。<span class="marginnote">数字实例：\\(1\\ \\text{TiB} \\div 4\\ \\text{KiB} \\approx 2.68\\) 亿条表项，每条 4 字节就是约 1 GiB 的映射表——这笔 DRAM 要常驻在盘里，这就是页级映射「随机写零合并」的定价。</span>块级映射：表极小，但小随机写逼着 FTL 搬整块有效页来腾位置。折中是混合式：新写先进 log 区顺序落，log 块装满再按数据块做合并或交换；顺序写近乎免费，随机写把 log 块与数据块的交换搅成搬运风暴。粒度选择因此是表容量与随机写搬运量的三方权衡，没有两端都赢的解。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第二个旋钮是超配（OP）：物理容量中不开放给用户的那部分，专供 GC 挑空块。预留越多，GC 选块越从容，随机写的写放大越低；消费级常见约 7%，企业级 20% 到 28%——同一份 NAND，OP 差三倍，随机写寿命兑现可以差数倍。<a href="/cs/discard-trim">TRIM</a> 把已删空间提前告诉 FTL，相当于临时扩大 OP，这是软件不花钱就能买到的写放大折扣。<span class="marginnote">常见误区：以为删除文件就腾出了盘内的空间。块接口并不知道哪些页已经死了，TRIM（discard）就是把这个消息递给 FTL 的接口——不开 TRIM，已删数据照样占着 GC 的搬运量。</span>耐久账随之而来：TLC 颗粒的擦写次数以千计，若业务持续随机写被 FTL 放大十倍，介质承受的字节流速就是十倍，寿命按同倍数折损——「这块盘写不死」的判断必须用 WAF 校正后再下。</p><p>主机能替 FTL 做的事按介入深度排：把负载顺序化（<a href="/cs/log-structured-fs">LFS</a> 与 <a href="/cs/f2fs">F2FS</a> 已在文件系统层做过一遍）；用 multi-stream 给写打流标签，让 FTL 按流分区回收，冷热不再混块；更彻底是 ZNS，把空间划成必须顺序写的区域，合并逻辑整体还给主机——FTL 退化成一个薄映射，GC 的账由文件系统自己算。介入越深，主机接管的责任越多，与网络课「每下移一层，内核职责改名由你承担」是同一句合同。</p>',8)),(t(),B(i,null,{default:E(()=>[l(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%B8%BB%E6%9C%BA%E5%86%99%20LBA%22%5D%20--%3E%20F%5B%22FTL%20%E5%88%86%E6%B5%81%22%5D%0A%20%20F%20--%3E%7C%22%E9%A1%BA%E5%BA%8F%2F%E5%A4%A7%E5%9D%97%22%7C%20SEQ%5B%22%E6%95%B0%E6%8D%AE%E5%8C%BA%E7%9B%B4%E6%8E%A5%E8%90%BD%E4%BD%8D%22%5D%0A%20%20F%20--%3E%7C%22%E9%9A%8F%E6%9C%BA%E5%B0%8F%E5%86%99%22%7C%20LOG%5B%22log%20%E5%8C%BA%E9%A1%BA%E5%BA%8F%E5%86%99%22%5D%0A%20%20LOG%20--%3E%20FULL%7B%22log%20%E5%9D%97%E6%BB%A1%22%7D%0A%20%20FULL%20--%3E%20MERGE%5B%22%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%9D%97%E5%90%88%E5%B9%B6%E6%88%96%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20MERGE%20--%3E%20OP%5B%22OP%20%E7%A9%BA%E9%97%B2%E5%9D%97%E8%A1%A5%E7%BB%99%20GC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[e("随机写贵的机制可以一笔账写清：GC 选中的擦除块里有效页占比 \\(p\\)，释放一块就要先搬 \\(p\\) 块的数据。顺序写让块整块变旧、\\(p\\) 趋近于零，写放大约为 1；持续的小随机写让每个块都半新不旧，\\(p\\) 居高不下，写放大随之爬到数倍到十倍。OP 的作用就是给 FTL 挑选低 \\(p\\) 块的余地。这也解释了为什么「随机写性能」在 SSD 上是一段会掉下去的曲线：写入速率长期超过 GC 消化速率时，盘先是耗尽 OP 空闲块，再把主机写速压到 GC 速率——稳态吞吐由回收速率决定，不由颗粒的编程带宽决定。"),s("span",{class:"marginnote"},"直觉类比：GC 像搬宿舍——房间里还留着九成没拆封的纸箱（\\(p=0.9\\)），为腾这一间得先搬九间的东西；住满即搬空的房间（顺序写）几乎是白腾。")],-1)),(t(),B(i,null,{default:E(()=>[l(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20GC%5B%22GC%20%E9%80%89%E4%B8%AD%E4%B8%80%E5%9D%97%E5%BE%85%E6%93%A6%E9%99%A4%22%5D%20--%3E%20P%7B%22%E5%9D%97%E5%86%85%E6%9C%89%E6%95%88%E9%A1%B5%E5%8D%A0%E6%AF%94%20p%EF%BC%9F%22%7D%0A%20%20P%20--%3E%7C%22%E9%A1%BA%E5%BA%8F%E5%86%99%EF%BC%9Ap%20%E8%BF%91%200%22%7C%20FREE%5B%22%E7%9B%B4%E6%8E%A5%E6%93%A6%EF%BC%8C%E5%86%99%E6%94%BE%E5%A4%A7%E7%BA%A6%201%22%5D%0A%20%20P%20--%3E%7C%22%E9%9A%8F%E6%9C%BA%E5%86%99%EF%BC%9Ap%20%E5%B1%85%E9%AB%98%22%7C%20COPY%5B%22%E5%85%88%E6%90%AC%20p%20%E6%AF%94%E4%BE%8B%E7%9A%84%E6%9C%89%E6%95%88%E9%A1%B5%22%5D%0A%20%20COPY%20--%3E%20WA%5B%22%E5%86%99%E6%94%BE%E5%A4%A7%E5%8D%87%E8%87%B3%E6%95%B0%E5%80%8D%E4%BB%A5%E4%B8%8A%22%5D%0A%20%20WA%20--%3E%20OPQ%7B%22OP%20%E7%A9%BA%E9%97%B2%E5%9D%97%E8%BF%98%E5%A4%9F%EF%BC%9F%22%7D%0A%20%20OPQ%20--%3E%7C%22%E6%98%AF%22%7C%20KEEP%5B%22%E7%BB%B4%E6%8C%81%E9%AB%98%E5%86%99%E9%80%9F%22%5D%0A%20%20OPQ%20--%3E%7C%22%E5%90%A6%22%7C%20CLIFF%5B%22%E5%86%99%E9%80%9F%E8%A2%AB%E5%8E%8B%E5%88%B0%20GC%20%E7%A8%B3%E6%80%81%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">数字锚点：TLC 页编程以数百微秒到毫秒计，擦除以毫秒到十毫秒计，而页读只要几十微秒——GC 搬一块等于整块的读加写，这就是为什么读为主的盘几乎感受不到 FTL，写为主的盘处处是它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲 NAND 物理与 L2P 恢复（<a href="/cs/nand-ftl">NAND 闪存与 FTL</a> 已钉）、不展开并行结构与磨损均衡（<a href="/cs/ssd-gc-wear">SSD 内部课</a>已给）、不进 NVMe 队列细节（<a href="/cs/nvme-driver">NVMe 驱动</a>另有专课）。读扰动、保持期与纠错只点名存在，不展开工艺。后课默认：块接口下有按块擦写的介质，WAF 是 FTL 对写负载的报价。下一课转向分析型负载：当数据离开引擎自己的页合同、装进开放文件时，合同怎么签。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>映射粒度三方权衡：页级表大随机写零合并，块级表小小随机写搬块，混合式居中。</li><li>OP 是写放大的价格旋钮：7% 到 28% 的预留差，随机写寿命兑现差数倍；TRIM 是免费的 OP 补贴。</li><li>GC 成本由块内有效页占比决定：顺序写近似免费，小随机写把曲线压到 GC 稳态。</li><li>主机介入谱系：顺序化、multi-stream、ZNS，介入越深责任越多。</li><li>出处：Agrawal et al., USENIX ATC 2008；Desnoyers, SYSTOR 2012；NVMe ZNS 与 ONFI 规范。</li></ul>',5))])}const h=o(C,[["render",F]]);export{S as __pageData,h as default};
